#!/usr/bin/env python3
"""Write every condition's frozen system prompt verbatim to docs/prompts.md.

The paper's appendix is generated from this file, so the prompts reviewers
read are byte-identical to the ones the harness sent.

Run:  uv run --no-project --with anthropic python3 scripts/dump_prompts.py
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from extract_pairs import REPO  # noqa: E402
from multi_model_compare import CONDITIONS  # noqa: E402

out = ["# Frozen system prompts, by condition", "",
       "Generated by `scripts/dump_prompts.py` from `multi_model_compare.CONDITIONS`.", ""]
for name, (system, _) in CONDITIONS.items():
    out += [f"## {name}", "", "```", system.strip(), "```", ""]
(REPO / "docs/prompts.md").write_text("\n".join(out))
print(f"wrote docs/prompts.md ({len(CONDITIONS)} conditions)")
